import * as XLSX from 'xlsx-js-style';
import { datosFormato, lineaGenerado, type ContextoDocumento } from './index';

type Valor = string | number | boolean | null;
const negrita = { font: { bold: true, sz: 12 } };
const suave = { font: { italic: true, sz: 9, color: { rgb: '555555' } } };
const cabecera = { font: { bold: true }, fill: { fgColor: { rgb: 'DCE6F1' } }, border: { bottom: { style: 'thin' } } };

/** Top rows (company, title, code/version/validity, sheet) and footer rows (legends, generated by · folio). */
export function filasIdentidad(c: ContextoDocumento, hoja = 1, totalHojas = 1) {
  const superiores: Valor[][] = [
    [c.razonSocial], [c.titulo],
    [[...datosFormato(c), `Hoja ${hoja} de ${totalHojas}`].join(' · ')],
    ...(c.domicilio ? [[c.domicilio]] : []),
    [],
  ];
  const pie: Valor[][] = [[], ...c.leyendas.map(l => [l]), [lineaGenerado(c)]];
  return { superiores, pie };
}

/** Sheet with identity rows above the table header and footer rows below. Excel has no image support here: logo is omitted, company name is shown. */
export function hojaConIdentidad(c: ContextoDocumento, encabezados: string[], datos: Valor[][], hoja = 1, totalHojas = 1, extras: Valor[][] = []) {
  const { superiores, pie } = filasIdentidad(c, hoja, totalHojas);
  const arriba = [...superiores, ...extras, ...(extras.length ? [[]] : [])];
  const ws = XLSX.utils.aoa_to_sheet([...arriba, encabezados, ...datos, ...pie]);
  const set = (r: number, cc: number, s: object) => { const ref = XLSX.utils.encode_cell({ r, c: cc }); if (ws[ref]) ws[ref].s = s; };
  set(0, 0, negrita); set(1, 0, { font: { bold: true, sz: 11 } }); set(2, 0, suave);
  encabezados.forEach((_, i) => set(arriba.length, i, cabecera));
  const ini = arriba.length + 1 + datos.length;
  pie.forEach((_, i) => set(ini + i, 0, suave));
  return ws;
}

export const escribirLibro = (wb: XLSX.WorkBook) => new Uint8Array(XLSX.write(wb, { type: 'array', bookType: 'xlsx' }));
export { XLSX };
